-- Publish the user-supplied Neuroanatomia pack after R2 checksum verification.
-- Archive the previous editions while preserving their records and references.
UPDATE material_anki_decks SET publication_status='archived',updated_at=unixepoch()*1000
WHERE id IN ('anki-neuro-essential','anki-neuro-complete');

