INSERT INTO admin_audit_log(actor_user_id,action,details,created_at)
SELECT id,'materials_anki_published','{"source":"authorized-neuro-anki-2026-10-01","deck":"anki-neuro-at1-at21-ap1-ap13","cards":3079,"archivedEditions":2}',unixepoch()*1000
FROM users WHERE status='active' AND (commission_position='principal_admin' OR role='admin')
AND NOT EXISTS(SELECT 1 FROM admin_audit_log WHERE action='materials_anki_published' AND details LIKE '%authorized-neuro-anki-2026-10-01%')
ORDER BY CASE WHEN commission_position='principal_admin' THEN 0 ELSE 1 END,created_at LIMIT 1;
